"use client";

/**
 * @file `useCollectionCreate`: state + handlers for creating one new item.
 * Owns the new-item draft lifecycle against the collection's pending virtual
 * row (seed on arrival, debounced autosave, cleanup on cancel) and the submit.
 * Shared by the drawer's "+ Yeni" card and the page-level
 * `<CollectionComposer>`; the caller owns all chrome and must mount this only
 * where `canCreate` is true.
 *
 * Two ways to publish, decided by the collection's `slugSource`. Only the
 * request differs; the draft slot is the same slug-less one either way:
 *
 *   - `AutoGenerated` — `POST /cms/collections/{key}`, backend derives the slug.
 *   - `UserDefined` — `PUT /cms/collections/{key}/{slug}` with `version: null`
 *     at the slug the caller passes. That endpoint upserts, so an existing slug
 *     is what the version guard catches (see `submit`).
 */

import { useEffect, useMemo, useRef, useState, useTransition } from "react";

import { useCmsContext } from "../../shared/state/cms-context.js";
import { useCmsStrings } from "../../core/hooks/use-cms-strings.js";
import { useCollectionContext } from "../context.js";
import { itemDraftKey, newDraftKey } from "../../shared/state/draft-keys.js";
import { useCollection } from "./use-collection.js";
import { useCollectionLocale } from "./use-collection-locale.js";
import { useCollectionMeta } from "./use-my-collections.js";
import { CmsApiError } from "../../shared/contracts/errors.js";
import { stableStringify } from "../../shared/util/stable-stringify.js";
import { seedValues, buildPayload, requiredMissing } from "../record-payload.js";
import { humanizeCollectionError } from "../record-errors.js";


/**
 * @typedef {Object} CollectionCreateState
 * @property {Record<string, *>} values
 * @property {(next: Record<string, *>) => void} setValues
 * @property {(onCreated?: (item: import("../../shared/contracts/schemas.js").CollectionItemResponse) => void) => void} submit
 * @property {() => void} reset          Clear local values back to the empty seed.
 * @property {() => void} deleteDraft    Fire-and-forget wipe of the backend's new-item draft slot.
 * @property {boolean} hasServerDraft    A stashed new-item draft exists on the backend.
 * @property {boolean} isPending
 * @property {string | null} error
 */

/**
 * @param {Object} options
 * @param {string} options.collectionKey
 * @param {import("../../shared/contracts/schemas.js").CollectionSchema} options.schema
 * @param {import("../../shared/contracts/schemas.js").CollectionListParams} [options.listParams]
 *   List window used to find the pending draft row. Any window carries it, so
 *   the drawer passes the page's own to collapse the lookup onto an existing
 *   cache entry; standalone surfaces default to the plain first page.
 * @param {boolean} [options.active=true]  Autosave only while true (the
 *   drawer's collapsed card passes its open state), so an untouched closed
 *   form never PUTs.
 * @param {() => void} [options.onSeedFromDraft]  Fired once when a stashed
 *   backend draft seeds the form, so the caller can e.g. auto-expand.
 * @param {string} [options.translationOf]
 *   `translationGroupId` of a record this new one is a translation of. Read it
 *   off the record the editor is looking at; the backend links the two.
 * @param {string} [options.locale]
 *   Language to compose in. Defaults to the route's when the collection holds
 *   that language, which is right for a plain "new record" flow. A translation
 *   is the exception: the editor is reading the Turkish page while writing the
 *   English copy, so that flow names it.
 * @param {string} [options.slug]
 *   `UserDefined` collections only, where it is required: the slug the editor
 *   typed. Held by the caller rather than in here because the backend's draft
 *   slot doesn't store it, so it is form state that dies with the pane.
 * @returns {CollectionCreateState}
 */
export function useCollectionCreate({
  collectionKey,
  schema,
  listParams,
  active = true,
  onSeedFromDraft,
  translationOf,
  locale: localeProp,
  slug,
}) {
  const { config, getAccessToken, onAfterCollectionSave } = useCmsContext();
  const t = useCmsStrings();
  const { updateCollectionItem, invalidateCollectionList, patchCollectionPendingDraft, draftQueue } =
    useCollectionContext();
  // A record is composed in the language of the page composing it, unless the
  // caller is writing a translation and says otherwise.
  const collectionLocale = useCollectionLocale(collectionKey);
  const locale = localeProp ?? collectionLocale;
  const needsSlug = useCollectionMeta(collectionKey)?.slugSource === "UserDefined";

  const [values, setValues] = useState(() => seedValues(schema.fields, {}));
  const [error, setError] = useState(/** @type {string | null} */ (null));
  const [isPending, startTransition] = useTransition();

  const stableListParams = useMemo(
    () => listParams ?? { limit: 50 },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [stableStringify(listParams ?? null)],
  );
  const { virtualItems } = useCollection(collectionKey, stableListParams);
  const draftEntry = useMemo(
    // `pending` is the collection's single new-item slot; the `derived` rows
    // alongside it are claim-derived slugs, each with a draft slot of its own.
    () => virtualItems.find((row) => row.origin === "pending") ?? null,
    [virtualItems],
  );
  const draftData = draftEntry?.draftData ?? null;

  const lastSyncedRef = useRef(/** @type {string | null} */ (null));
  const onSeedRef = useRef(onSeedFromDraft);
  onSeedRef.current = onSeedFromDraft;

  // Seed from the backend draft once, on the null->object flip, so a publish
  // (which clears the draft) doesn't re-seed against the just-emptied values.
  const seededRef = useRef(false);
  useEffect(() => {
    if (seededRef.current) return;
    if (!draftData) return;
    setValues(seedValues(schema.fields, draftData));
    lastSyncedRef.current = stableStringify(draftData);
    seededRef.current = true;
    onSeedRef.current?.();
  }, [draftData, schema.fields]);

  // Debounced autosave of the in-progress values into the new-item draft
  // slot. Skips the pristine empty seed so an opened-then-ignored form never
  // creates a phantom draft.
  useEffect(() => {
    if (!active) return undefined;
    if (isPending) return undefined;
    const payload = buildPayload(schema.fields, values);
    const serialized = stableStringify(payload);
    if (serialized === lastSyncedRef.current) return undefined;
    if (lastSyncedRef.current === null && serialized === stableStringify(buildPayload(schema.fields, seedValues(schema.fields, {})))) {
      return undefined;
    }

    // Same lane as a virtual row's editor: both POST to the collection's single
    // new-item slot, so they must not be able to overlap.
    draftQueue.schedule(newDraftKey(collectionKey, locale), async (ctx) => {
      try {
        const token = await getAccessToken();
        await config.transport.saveCollectionNewDraft(
          collectionKey,
          { data: payload },
          { accessToken: token, locale: locale ?? undefined, translationGroup: translationOf },
        );
        if (ctx.isStale()) return;
        lastSyncedRef.current = serialized;
        // Marked before the patch below: the seeding effect reads the same
        // `draftData` we are about to write, and re-seeding from it would drop
        // whatever was typed while the request was in flight.
        seededRef.current = true;
        patchCollectionPendingDraft(collectionKey, locale ?? null, payload);
      } catch (err) {
        if (ctx.isStale()) return;
        // eslint-disable-next-line no-console
        console.warn("[inscribed] collection new-draft autosave failed:", err);
      }
    });
    return undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [values, active, isPending, collectionKey, locale, translationOf]);

  const reset = () => {
    setValues(seedValues(schema.fields, {}));
    setError(null);
    lastSyncedRef.current = null;
    seededRef.current = false;
  };

  const deleteDraft = async () => {
    // A queued autosave for this slot is now obsolete; dropping it here stops
    // it re-creating the draft this call is removing.
    draftQueue.cancel(newDraftKey(collectionKey, locale));
    try {
      const token = await getAccessToken();
      await config.transport.deleteCollectionNewDraft(collectionKey, {
        accessToken: token,
        locale: locale ?? undefined,
      });
      // List invalidation is enough: the pending row only ever reaches
      // consumers through the list window, never through the item cache.
      invalidateCollectionList(collectionKey);
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn("[inscribed] collection new-draft delete failed:", err);
    }
  };

  const submit = (onCreated) => {
    setError(null);
    const missing = requiredMissing(schema.fields, values);
    if (missing) {
      setError(t("collections.requiredMissing", { field: missing }));
      return;
    }
    const ownSlug = slug?.trim();
    if (needsSlug && !ownSlug) {
      setError(t("collections.slugMissing"));
      return;
    }
    startTransition(async () => {
      try {
        const token = await getAccessToken();
        const payload = { data: buildPayload(schema.fields, values) };
        // `translationGroup` reaches the POST only: the per-slug PUT carries no
        // such parameter, so a UserDefined collection cannot link a new record
        // into an existing translation group yet.
        const created = needsSlug
          ? await config.transport.upsertCollectionItem(
            collectionKey,
            ownSlug,
            { ...payload, version: null },
            { accessToken: token, locale: locale ?? undefined },
          )
          : await config.transport.createCollectionItem(
            collectionKey,
            payload,
            { accessToken: token, locale: locale ?? undefined, translationGroup: translationOf },
          );
        // The new-item slot no longer describes anything, so a queued write
        // against it is dropped; the record's own lane inherits whatever is
        // still in flight, so its first draft write can't overtake the create.
        draftQueue.rename(
          newDraftKey(collectionKey, locale), itemDraftKey(collectionKey, created.slug),
        );
        updateCollectionItem(collectionKey, created.slug, created);
        // A new row changes every server-rendered window of this collection.
        try {
          await onAfterCollectionSave(collectionKey, created.slug);
        } catch (revalidateErr) {
          // eslint-disable-next-line no-console
          console.warn("[inscribed] onAfterCollectionSave failed:", revalidateErr);
        }
        reset();
        onCreated?.(created);
      } catch (err) {
        if (err instanceof CmsApiError && err.isConflict) {
          // A write race, not a version clash: creates carry no version. Two
          // surfaces POSTing the collection's single new-item slot is the way
          // in (see the `active` contract in use-collection-editor.js).
          setError(t("collections.createRace"));
        } else if (err instanceof CmsApiError && err.isForbidden) {
          setError(t("collections.createForbidden"));
        } else if (err instanceof CmsApiError && err.status === 400
          && needsSlug && /version/i.test(err.detail ?? "")) {
          // The upsert found a row where this create said there was none, and
          // answers "Version is required when writing to existing item". Read
          // ahead of the humanizer below, which turns every 400 into a
          // data-is-invalid banner, and matched on the text because this one
          // carries no machine-readable reason the way the archived 409 does.
          setError(t("collections.slugTaken"));
        } else if (err instanceof CmsApiError && err.status === 400) {
          // Backend reports inner failures as `works[0].title`; map onto
          // schema labels for a readable banner.
          setError(
            humanizeCollectionError(err.detail, schema.fields, t)
            ?? t("collections.invalidData", { detail: err.message }),
          );
        } else {
          setError(/** @type {Error} */ (err).message);
        }
      }
    });
  };

  return {
    values,
    setValues,
    submit,
    reset,
    deleteDraft,
    hasServerDraft: draftData != null,
    isPending,
    error,
  };
}
